const sql=`SELECT r."USGSPCode" pcode, r."ResultMeasure/MeasureUnitCode" unit, r."ResultStatusIdentifier" status, r."ResultValueTypeName" vtype,
COUNT(*) n
FROM r JOIN s ON r."MonitoringLocationIdentifier"=s."MonitoringLocationIdentifier"
WHERE s."MonitoringLocationName" LIKE 'Trinity Rv %'
AND s."MonitoringLocationTypeName" IN ('Stream','Stream: Tidal stream')
AND r."ActivityTypeCode"='Sample-Routine' AND r."ActivityMediaName"='Water'
AND r."USGSPCode" IN ('00010','00095','00300','00400')
GROUP BY 1,2,3,4 ORDER BY 1,2,3,4`;
