const sql=`WITH RECURSIVE years(y) AS (SELECT 2000 UNION ALL SELECT y+1 FROM years WHERE y<2019),
sy AS (
 SELECT station, CAST(substr(dt,1,4) AS INT) y
 FROM c GROUP BY station,y
 HAVING COUNT(DISTINCT CASE
 WHEN CAST(substr(dt,6,2) AS INT)<=3 THEN 1 WHEN CAST(substr(dt,6,2) AS INT)<=6 THEN 2
 WHEN CAST(substr(dt,6,2) AS INT)<=9 THEN 3 ELSE 4 END)=4
), intervals AS (
 SELECT a.y sy,b.y ey,b.y-a.y+1 dur FROM years a JOIN years b ON b.y>=a.y
), members AS (
 SELECT i.sy,i.ey,i.dur,s.station FROM intervals i JOIN sy s ON s.y BETWEEN i.sy AND i.ey
 GROUP BY i.sy,i.ey,i.dur,s.station HAVING COUNT(*)=i.dur
), designs AS (
 SELECT sy,ey,dur,COUNT(*) coverage FROM members GROUP BY sy,ey,dur HAVING COUNT(*)>=2
), frontier AS (
 SELECT d.* FROM designs d WHERE NOT EXISTS (
 SELECT 1 FROM designs x WHERE x.dur>=d.dur AND x.coverage>=d.coverage AND (x.dur>d.dur OR x.coverage>d.coverage))
)
SELECT f.sy,f.ey,f.dur,f.coverage,
(SELECT group_concat(station,';') FROM (SELECT station FROM members m WHERE m.sy=f.sy AND m.ey=f.ey ORDER BY station)) cohort
FROM frontier f ORDER BY sy,ey`;
const z=await tools.mcp__wqp_data__query_csv({tables:{c:"d0008"},sql,limit:200}); text(z);

const sql=`WITH cq AS (
 SELECT station,CAST(substr(dt,1,4) AS INT) y,
 CASE WHEN CAST(substr(dt,6,2) AS INT)<=3 THEN 1 WHEN CAST(substr(dt,6,2) AS INT)<=6 THEN 2 WHEN CAST(substr(dt,6,2) AS INT)<=9 THEN 3 ELSE 4 END q,
 COUNT(*) n
 FROM c GROUP BY station,y,q
), sy AS (SELECT station,y FROM cq GROUP BY station,y HAVING COUNT(*)=4)
SELECT c.* FROM c JOIN cq ON cq.station=c.station AND cq.y=CAST(substr(c.dt,1,4) AS INT)
AND cq.q=CASE WHEN CAST(substr(c.dt,6,2) AS INT)<=3 THEN 1 WHEN CAST(substr(c.dt,6,2) AS INT)<=6 THEN 2 WHEN CAST(substr(c.dt,6,2) AS INT)<=9 THEN 3 ELSE 4 END
JOIN sy ON sy.station=c.station AND sy.y=cq.y WHERE cq.n=1 ORDER BY act`;
