const sql=`WITH act AS (SELECT * FROM a1 UNION ALL SELECT * FROM a2),
elig AS (SELECT DISTINCT "OrganizationIdentifier" org,"ActivityIdentifier" aid,"MonitoringLocationIdentifier" site,"ActivityStartDate" dt,"ActivityStartTime/Time" tm,"ActivityDepthHeightMeasure/MeasureValue" depth_val,"ActivityDepthHeightMeasure/MeasureUnitCode" depth_unit FROM act WHERE "ActivityMediaName"='Water' AND "ActivityTypeCode"='Sample-Routine'),
usable AS (SELECT e.*,r."USGSPCode" pc,CAST(r."ResultMeasureValue" AS REAL) v FROM elig e JOIN r ON r."OrganizationIdentifier"=e.org AND r."ActivityIdentifier"=e.aid AND r."MonitoringLocationIdentifier"=e.site AND r."ActivityStartDate"=e.dt WHERE r."ResultStatusIdentifier" IN ('Accepted','Final') AND r."ResultValueTypeName"='Actual' AND COALESCE(r."ResultDetectionConditionText",'')='' AND COALESCE(r."MeasureQualifierCode",'')='' AND ((r."USGSPCode"='00010' AND r."ResultMeasure/MeasureUnitCode"='deg C') OR (r."USGSPCode"='00095' AND r."ResultMeasure/MeasureUnitCode" IN ('uS/cm @25C','uS/cm','umhos/cm','micromhos/cm')) OR (r."USGSPCode"='00300' AND lower(r."ResultMeasure/MeasureUnitCode")='mg/l') OR (r."USGSPCode"='00400' AND r."ResultMeasure/MeasureUnitCode"='std units'))),
oneval AS (SELECT org,aid,site,dt,tm,depth_val,depth_unit,pc,MIN(v) v,COUNT(DISTINCT v) nv FROM usable GROUP BY org,aid,site,dt,tm,depth_val,depth_unit,pc),
complete AS (SELECT org,aid,site,dt,tm,depth_val,depth_unit,MAX(CASE WHEN pc='00010' THEN v END) temp,MAX(CASE WHEN pc='00095' THEN v END) cond,MAX(CASE WHEN pc='00300' THEN v END) do,MAX(CASE WHEN pc='00400' THEN v END) ph FROM oneval GROUP BY org,aid,site,dt,tm,depth_val,depth_unit HAVING COUNT(*)=4 AND MAX(nv)=1)
SELECT *, CAST(substr(dt,1,4) AS INTEGER) yr, CAST((CAST(substr(dt,6,2) AS INTEGER)-1)/3 AS INTEGER)+1 qtr FROM complete ORDER BY aid`;
