const sql=`WITH years(y) AS (VALUES(2000),(2001),(2002),(2003),(2004),(2005),(2006),(2007),(2008),(2009),(2010),(2011),(2012),(2013),(2014),(2015),(2016),(2017),(2018),(2019)),
ints AS (SELECT a.y sy,b.y ey,b.y-a.y+1 dur FROM years a JOIN years b ON b.y>=a.y),
sup AS (SELECT site,yr FROM c GROUP BY site,yr HAVING COUNT(DISTINCT qtr)=4),
cs AS (SELECT i.sy,i.ey,i.dur,s.site FROM ints i JOIN sup s ON s.yr BETWEEN i.sy AND i.ey GROUP BY i.sy,i.ey,i.dur,s.site HAVING COUNT(DISTINCT s.yr)=i.dur),
d AS (SELECT sy,ey,dur,COUNT(*) coverage FROM cs GROUP BY sy,ey,dur HAVING COUNT(*)>=2),
f AS (SELECT d.* FROM d WHERE NOT EXISTS (SELECT 1 FROM d x WHERE x.dur>=d.dur AND x.coverage>=d.coverage AND (x.dur>d.dur OR x.coverage>d.coverage)))
SELECT f.*, (SELECT group_concat(site,';') FROM (SELECT site FROM cs WHERE sy=f.sy AND ey=f.ey ORDER BY site)) cohort FROM f ORDER BY sy,ey`;
