const sql=`WITH scenarios AS (
 SELECT f.wid,f.sy,f.ey,f.coverage,f.cohort,w.org worg,w.site wsite,w.dt wdt,w.qtr wq
 FROM f JOIN c w ON w.aid=f.wid
), candidates AS (
 SELECT s.*,c.org,c.site,c.aid,c.dt,c.tm,c.do,c.temp,c.cond,c.ph,
 COUNT(*) OVER (PARTITION BY s.wid,s.sy,s.ey) activity_count,
 ROW_NUMBER() OVER (PARTITION BY s.wid,s.sy,s.ey ORDER BY c.do ASC,c.dt ASC,CASE WHEN COALESCE(c.tm,'')='' THEN 1 ELSE 0 END ASC,c.tm ASC,c.site ASC,c.aid ASC) rn
 FROM scenarios s JOIN c ON c.aid<>s.wid AND c.yr BETWEEN s.sy AND s.ey AND c.qtr=s.wq
 AND instr(';'||s.cohort||';',';'||c.site||';')>0
)
SELECT worg||'|'||wid||'|'||wsite||'|'||wdt||'|'||sy||'|'||ey||'|'||coverage||'|'||cohort||'|Q'||wq||'|'||activity_count||'|'||org||'|'||site||'|'||aid||'|'||dt||'|'||printf('%.2f',do)||'|'||printf('%.2f',temp)||'|'||printf('%.2f',cond)||'|'||printf('%.2f',ph) line
FROM candidates WHERE rn=1 ORDER BY wid,sy,ey`;
